import {LIFE_TOOLS,LIFE_ORDERS,TRANSPORTS,CART_RECIPE,UPGRADE_GATES,reputationName,orderReward,transportReward,ensureOrders,hasMaterials,focusOrder,deliverOrder,buyTool,commissionCart,buildCart,startTransport,cancelTransport,deliverTransport} from './life-progression.js?v=49';
import {CROPS,plantBatch,activePlots,plotState,harvestCrop,setLifeLevel} from './homestead.js?v=49';
export function createLifeCommerceUI(api){
 const {$,panel,imageTag,toast,save,hud,travel,esc}=api,s=()=>api.state(),h=()=>s().ancient.home;
 const done=text=>{save();hud();toast(text);};
 const picture=(id,name)=>imageTag(id,name);
 const goods=items=>Object.entries(items).map(([id,n])=>`${api.items[id].name} ${s().inventory[id]||0} / ${n}`).join(' · ');
 const cost=items=>Object.entries(items).map(([id,n])=>`${api.items[id].name} ${n}개`).join(' · ');
 function board(){if(!h().owned)return;if(ensureOrders(s()))save();const c=h().commerce,inVillage=s().map==='ancient-village-'+s().ancient.country;
  panel('마을의 부탁',`<div class="life-order-heading">${picture('life-requestBoard','마을 부탁 게시판')}<div><h3>우리 마을에 필요한 물건</h3><p>${reputationName(h().reputation)} · 평판 ${h().reputation}/100</p><p>${s().coins}엽전 · 부탁 ${c.completed}회 완료</p></div></div><div class="life-order-grid">${c.orders.map(o=>{const d=LIFE_ORDERS[o.key],ready=hasMaterials(s(),d.items);return `<article class="life-order ${c.focus===o.id?'selected':''}">${picture(d.art,d.name)}<h3>${d.name}</h3><p>${goods(d.items)}</p><small>보상 ${orderReward(d)}엽전 · 평판 +${d.rep}</small><button data-order-deliver="${o.id}" ${!inVillage||!ready?'disabled':''}>${ready?'납품하기':'물건을 모아 오자'}</button><button data-order-focus="${o.id}">${c.focus===o.id?'선택 취소':'이 부탁 기억하기'}</button></article>`;}).join('')}</div><p class="note">납품할 때만 물건을 건네. 선택을 취소해도 잃는 것은 없어. 새로고침해도 부탁은 그대로야.</p>${!inVillage?'<button id="life-visit-board" class="primary full">마을 게시판으로 가기</button>':''}<button id="life-cart-menu" class="full">목수 · 수레와 운송</button><button id="life-board-home" class="full">내 거처로</button>`,{wide:true,type:'life-orders'});
  document.querySelectorAll('[data-order-deliver]').forEach(b=>b.onclick=()=>{const r=deliverOrder(s(),Number(b.dataset.orderDeliver));if(r)done(`${r.reward}엽전 · 평판 +${r.rep}!`);board();});
  document.querySelectorAll('[data-order-focus]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.orderFocus);focusOrder(s(),c.focus===n?null:n);save();board();});
  const go=$('#life-visit-board');if(go)go.onclick=()=>{travel('ancient-village-'+s().ancient.country);board();};$('#life-cart-menu').onclick=cart;$('#life-board-home').onclick=()=>travel('ancient-home-'+s().ancient.country);
 }
 function toolCards(){return `<h3>살림을 편하게 하는 도구</h3><div class="life-shop-grid">${Object.entries(LIFE_TOOLS).map(([id,d])=>{const held=h().commerce.tools[id];return `<article>${picture(d.art,d.name)}<div><b>${d.name}</b><p>${d.text}</p><small>${d.coins}엽전 · ${cost(d.materials)}<br>거처 ${d.level}단계 · 평판 ${d.reputation} 필요</small></div><button data-life-tool="${id}" ${held||h().level<d.level||h().reputation<d.reputation||s().coins<d.coins||!hasMaterials(s(),d.materials)?'disabled':''}>${held?'마련함 ✓':'마련하기'}</button></article>`;}).join('')}</div>${h().commerce.legacyBulkHarvest&&!h().commerce.tools.sickle?'<p class="note">이전 기록의 모두 수확 기능은 계속 사용할 수 있어.</p>':''}<p class="note">낫에 필요한 가죽은 기존 사냥이나 마을 생활 재료 상점에서 마련할 수 있어.</p><button id="life-buy-hide" ${s().coins<30?'disabled':''}>가죽 1개 · 30엽전</button>`;}
 function bindTools(refresh){document.querySelectorAll('[data-life-tool]').forEach(b=>b.onclick=()=>{if(buyTool(s(),b.dataset.lifeTool))done('새 생활도구를 마련했다!');refresh();});const b=$('#life-buy-hide');if(b)b.onclick=()=>{if(s().coins>=30&&(s().inventory.hide||0)<99999){s().coins-=30;s().inventory.hide=(s().inventory.hide||0)+1;done('가죽을 마련했다.');}refresh();};}
 function batch(){if(!h().commerce.tools.seedBag)return;const empty=activePlots(h()).filter(p=>!p.crop);panel('씨앗 주머니',`<h3>심을 씨앗과 빈 칸을 골라 줘.</h3><label>씨앗<select id="life-batch-crop">${Object.entries(CROPS).filter(([id,c])=>h().seeds[id]>0&&empty.some(p=>p.id.startsWith(c.kind))).map(([id,c])=>`<option value="${id}">${c.name} · ${h().seeds[id]}개</option>`).join('')}</select></label><div class="life-batch-plots">${empty.map(p=>`<label><input type="checkbox" data-life-batch="${p.id}">${p.id.startsWith('field')?'밭':'논'} ${p.id.split('-')[1]}</label>`).join('')}</div><button id="life-batch-plant" class="primary full">고른 칸에 심기</button><p class="note">선택한 칸마다 씨앗 1개를 써. 성장시간과 수확량은 그대로야.</p><button id="life-batch-back" class="full">밭 보기</button>`,{wide:true});
  const update=()=>{const c=CROPS[$('#life-batch-crop').value];document.querySelectorAll('[data-life-batch]').forEach(b=>{b.disabled=!c||!b.dataset.lifeBatch.startsWith(c.kind);if(b.disabled)b.checked=false;});};$('#life-batch-crop').onchange=update;update();$('#life-batch-plant').onclick=()=>{const ids=[...document.querySelectorAll('[data-life-batch]:checked')].map(b=>b.dataset.lifeBatch);if(plantBatch(s(),ids,$('#life-batch-crop').value)){done(ids.length+'칸에 씨앗을 심었다.');api.openFarm();}else toast('빈 칸과 씨앗 개수를 확인해 줘.');};$('#life-batch-back').onclick=api.openFarm;
 }
 function hearth(){panel('거처의 화로',`<div class="life-order-heading">${picture(h().commerce.tools.hearth?'life-hearth':'campfire','거처 화로')}<div><h3>${h().commerce.tools.hearth?'넉넉해진 화로':'작은 화로'}</h3><p>재료를 익혀 따뜻한 음식을 만들자.</p></div></div><div class="life-shop-grid">${Object.entries(api.cooking).map(([id,out])=>`<article>${picture(api.items[out].art,api.items[out].name)}<div><b>${api.items[out].name}</b><p>${api.items[id].name} ${s().inventory[id]||0}개 · HP +${api.items[out].heal}</p></div><button data-life-cook="${id}" data-count="1" ${!s().artifacts.includes('fire')||(s().inventory[id]||0)<1?'disabled':''}>1개 조리</button>${h().commerce.tools.hearth?`<button data-life-cook="${id}" data-count="2" ${!s().artifacts.includes('fire')||(s().inventory[id]||0)<2?'disabled':''}>2개 함께 조리</button>`:''}</article>`).join('')}</div><button id="life-rest" class="full">잠시 쉬기</button>`,{wide:true});document.querySelectorAll('[data-life-cook]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.count);if(n===2&&!h().commerce.tools.hearth)return;const out=api.cook(b.dataset.lifeCook,n);if(out){api.finishEvent('cook:'+out);done(api.items[out].name+' '+n+'개를 만들었다.');}hearth();});$('#life-rest').onclick=()=>api.rest();}
 function cart(){const c=h().commerce.cart,village=s().map==='ancient-village-'+s().ancient.country;if(!village&&!c.active){travel('ancient-village-'+s().ancient.country);}
  const ready=h().level>=3&&s().coins>=CART_RECIPE.coins&&hasMaterials(s(),CART_RECIPE.materials);
  panel('마을 목수 · 작은 수레',`<div class="life-order-heading">${picture(c.owned?'life-cart-empty':'life-cart-plan','작은 목제 수레')}<div><h3>${c.owned?'내 물건을 싣고 강가로':'목수와 함께 수레 만들기'}</h3><p>${c.owned?'말은 개인 이동, 수레는 물건 운반이야.':'거처 3단계에서 작은 수레를 마련할 수 있어.'}</p></div></div>${!c.owned?`<p>${CART_RECIPE.coins}엽전 · ${cost(CART_RECIPE.materials)}</p><p>보유: ${goods(CART_RECIPE.materials)}</p>${c.commissioned?`<p>목수가 바퀴와 짐판을 만들 준비를 마쳤어.</p><button id="life-build-cart" class="primary full" ${ready?'':'disabled'}>재료 건네고 수레 완성하기</button>`:`<button id="life-ask-cart" class="primary full" ${h().level<3?'disabled':''}>목수에게 제작을 부탁하기</button>`}`:c.active?activeTransport():`<div class="life-order-grid">${Object.entries(TRANSPORTS).map(([key,d])=>`<article class="life-order">${picture(d.art,d.name)}<h3>${d.name}</h3><p>${goods(d.items)}</p><p>${d.text}</p><small>${transportReward(d)}엽전 · 평판 +${d.rep}</small><button data-life-transport="${key}" ${!hasMaterials(s(),d.items)||(s().progress.ancient||0)<20?'disabled':''}>짐 싣고 출발 준비</button></article>`).join('')}</div>${(s().progress.ancient||0)<20?'<p>이야기 책상에서 4세기 첫 준비를 마친 뒤 강가로 갈 수 있어.</p>':''}`}<p class="note">물건은 목적지에서만 건네. 도중에 취소해도 물건은 가방에 남아. 운송 중에는 걸어서 이동해.</p><button id="life-cart-back" class="full">마을 부탁 보기</button>`,{wide:true});
  if($('#life-ask-cart'))$('#life-ask-cart').onclick=()=>{if(commissionCart(s()))done('목수가 수레의 설계를 준비했다.');cart();};if($('#life-build-cart'))$('#life-build-cart').onclick=()=>{if(buildCart(s()))done('내 마당에 작은 수레가 생겼다!');cart();};document.querySelectorAll('[data-life-transport]').forEach(b=>b.onclick=()=>{if(startTransport(s(),b.dataset.lifeTransport))done('수레에 짐을 실었다. 강가 길로 걸어가자.');cart();});bindCancel(cart);$('#life-cart-back').onclick=board;
 }
 function activeTransport(){const a=h().commerce.cart.active,d=TRANSPORTS[a.key];return `<div class="life-transport-active"><h3>운송 중 · ${d.name}</h3><p>${d.text}</p><p>${goods(d.items)}</p><button id="life-cancel-transport">운송 취소 · 물건 유지</button></div>`;}
 function bindCancel(refresh){if($('#life-cancel-transport'))$('#life-cancel-transport').onclick=()=>{if(cancelTransport(s()))done('운송을 취소했다. 물건은 그대로 남아 있다.');refresh();};}
 function recipient(e){const a=h().commerce.cart.active,d=TRANSPORTS[a?.key],id=a?.id;panel(e.name,d&&d.target===e.id?`${picture(d.art,d.name)}<h3>${d.name}</h3><p>${goods(d.items)}</p><p>보상 ${transportReward(d)}엽전 · 평판 +${d.rep}</p><button id="life-transport-deliver" class="primary full" ${hasMaterials(s(),d.items)?'':'disabled'}>운송 물건 건네기</button>`:'<p>마을 목수에게 수레를 마련하면 이곳으로 물건을 운반할 수 있어.</p>');if($('#life-transport-deliver'))$('#life-transport-deliver').onclick=()=>{const r=deliverTransport(s(),e.id,id);if(r){done(`운송 완료! ${r.reward}엽전 · 평판 +${r.rep}`);api.close();}else toast('물건과 위치를 다시 확인해 줘.');};}
 function adminMarkup(){return `<div class="admin-section"><h3>생활 성장 2차</h3><div class="admin-grid">${[['new','새 거처 · 엽전 0'],['legacy','v48.1 거처 4단계'],['poor','부족한 엽전'],['rich','충분한 엽전'],['orders','부탁 생성 · 물건 부족'],['supplyOrders','부탁 완료 직전'],['complete','부탁 1회 완료'],['toolsOff','도구 미보유'],['toolsOn','도구 보유 · 일괄 농사'],['baseFire','기본 화로'],['betterFire','개선 화로'],['cartNone','수레 미보유'],['cartReady','수레 제작 재료'],['cartOwned','수레 보유'],['transport','운송 시작'],['arrival','운송 목적지'],['transportDone','운송 완료'],['cancel','운송 중도 취소'],['restore','저장 후 복원']].map(([id,name])=>`<button data-life2-qa="${id}">${name}</button>`).join('')}</div><div class="row">${[0,8,22,45,100].map(n=>`<button data-life2-rep="${n}">평판 ${n}</button>`).join('')}</div><label>누적 부탁<input id="life2-completed" type="number" min="0" max="99999" value="${h().commerce.completed}"></label><button id="life2-qa-count">완료 실적 적용</button></div>`;}
 function bindAdmin(refresh){document.querySelectorAll('[data-life2-rep]').forEach(b=>b.onclick=()=>{h().reputation=Number(b.dataset.life2Rep);save();refresh();});$('#life2-qa-count').onclick=()=>{const n=Number($('#life2-completed').value);if(Number.isInteger(n)&&n>=0&&n<=99999){h().commerce.completed=n;save();refresh();}};
 document.querySelectorAll('[data-life2-qa]').forEach(b=>b.onclick=()=>{const id=b.dataset.life2Qa;api.prepareAncient('4c');const st=s(),home=h(),c=home.commerce,village='ancient-village-'+st.ancient.country;api.adminJump(village);if(id==='new'){api.resetLife();st.coins=0;api.grantStarter();}if(id==='legacy'){setLifeLevel(home,4);home.paddies=2;c.legacyBulkHarvest=true;}
 if(id==='poor')st.coins=25;if(id==='rich')st.coins=3000;
 ensureOrders(st);if(['supplyOrders','complete'].includes(id)){for(const [key,n]of Object.entries(LIFE_ORDERS[c.orders[0].key].items))st.inventory[key]=n;if(id==='complete')deliverOrder(st,c.orders[0].id);}
 if(id==='orders')for(const o of c.orders)for(const key of Object.keys(LIFE_ORDERS[o.key].items))st.inventory[key]=0;
 if(['toolsOff','toolsOn','baseFire','betterFire'].includes(id)){for(const key of Object.keys(LIFE_TOOLS))c.tools[key]=id==='toolsOn';c.tools.hearth=id==='toolsOn'||id==='betterFire';if(id==='toolsOn'){for(const key of Object.keys(CROPS))home.seeds[key]=10;}api.adminJump('ancient-home-'+st.ancient.country);}
 if(id.startsWith('cart')||['transport','arrival','transportDone','cancel'].includes(id)){setLifeLevel(home,3);c.cart.active=null;c.cart.owned=!['cartNone','cartReady'].includes(id);c.cart.commissioned=id!=='cartNone';st.coins=1000;st.inventory.lumber=6;st.inventory.hide=2;if(['transport','arrival','transportDone','cancel'].includes(id)){st.progress.ancient=20;Object.assign(st.inventory,TRANSPORTS.grain.items);startTransport(st,'grain');if(id==='cancel')cancelTransport(st);if(id==='arrival'||id==='transportDone'){api.adminJump('ancient-han',{x:14,y:8.2});if(id==='transportDone')deliverTransport(st,'life-han-delivery',c.cart.active.id);}}}
 if(id==='restore')api.restoreTrial();save();refresh();});}
 function interact(e){if(e.type==='lifeRequests'){board();return true;}if(e.type==='lifeCarpenter'||e.id==='life-cart'){cart();return true;}if(e.type==='lifeDelivery'){recipient(e);return true;}if(e.id==='ancient-home-fire'){hearth();return true;}return false;}
 return {board,cart,hearth,batch,toolCards,bindTools,adminMarkup,bindAdmin,interact,activeTransport};
}
